  ('Mozzalloumi', 'What happens when you cross Mozzarella with Halloumi? Mozzalloumi!! It''s crispy with a gooey, melty middle and offers the best of both cheeses.', 6.99, 'each', 'Cheese', 'UK', 51.5, -0.13, false, ARRAY['nuts', 'soya'], ARRAY['dairy-free', 'gluten-free', 'vegan', 'vegetarian']),
